      },
      "R2": {
        "valeur": 1,
        "passage": "réécritures adoptées qui ne battent pas la consigne précédente sur des mondes frais (oracle) ; couverture des composantes plantées sur la famille jamais vue"
      },
      "R3": {
        "valeur": 1,
        "passage": "le vivier de conception (mondes plantés à graine scellée, jamais ceux du test)"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La construction de l'e-processus, notamment la règle de pari sur les différences de couverture, n'est pas spécifiée."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin à coût égal est nommé, mais le rejeu de journaux ou les quelques mondes neufs ne donnent aucun ordre de grandeur du coût en calcul, appels ou tirages."
      },
      "R7": {
        "valeur": 1,
        "passage": "la probabilité d'adopter une réécriture qui ne vaut pas mieux reste bornée au niveau choisi, même sous arrêt optionnel."
      },
      "N": {
        "valeur": "C7",
        "passage_fiche": "un e-processus par paris cumule la différence de couverture lue par l'oracle de ces mondes, et la réécriture est adoptée seulement quand la preuve accumulée devient décisive.",
        "passage_catalogue": "chaque candidate est comparée à la version en place **sur les mêmes instances**, et adoptée seulement quand un **e-processus par paris** accumule une preuve décisive"
      }
    },
    {
      "etiquette": "F02",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées couvertes augmente d'au moins 25 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de composantes plantées couvertes, lu par l'oracle après la course ; témoin : une modification tirée au hasard, au même coût"
      },
      "R3": {
        "valeur": 0,
        "motif": "Réduire m sans réduire les comparaisons correspondantes ni fournir une correction ne maintient pas le contrôle des comparaisons multiples exigé."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie conservée par le juge modifié ni le nul contre lequel elle resterait démontrable."
      },
      "R5": {
        "valeur": 1,
        "passage": "Réduire d'un tiers le nombre m fixé d'avance pour la règle de Benjamini et Hochberg sur les valeurs e."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que l'archive grandit plus ou moins vite selon m ne relie pas sa réduction à une augmentation des composantes vraies couvertes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
