        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "Réduire d'un tiers le nombre de générations par course."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le témoin à coût égal est nommé, mais la mention d'un rejeu sur processeur ne donne pas d'ordre de grandeur du coût de ce rejeu."
      },
      "R7": {
        "valeur": 0,
        "motif": "La réaction supposée des proposeurs à la forme plutôt qu'au fond n'explique pas pourquoi réduire le nombre de générations diminuerait les lois fausses promues."
      },
      "N": {
        "valeur": "aucune"
      }
