      },
      "R2": {
        "valeur": 0,
        "motif": "La qualité perçue et la richesse des idées relèvent d'une appréciation subjective, non de l'oracle ou du coût mesuré."
      },
      "R3": {
        "valeur": 1,
        "passage": "Ajouter à la consigne des proposeurs une invitation à réfléchir plus profondément et plus librement."
