      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne fixe pas le texte de l'invitation ni une procédure précise définissant la réflexion supplémentaire demandée."
      },
      "R6": {
        "valeur": 0,
        "motif": "Aucun contrôle négatif ou témoin à coût égal n'est nommé, et « presque rien » ne borne pas le coût d'une expérience décisive."
      },
      "R7": {
        "valeur": 0,
        "motif": "L'affirmation qu'une meilleure consigne rend les modèles plus créatifs est générique et ne fournit pas de mécanisme impliquant l'amélioration annoncée."
