      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : fausses, copies, composantes couvertes, par étage ; coût : calcul local seul, nombre de tirages frais égal ; témoin = nul actuel."
      },
      "R3": {
        "valeur": 1,
        "passage": "e-BH, m, test de mort inchangés. Fiche réservée au banc hors ligne avant toute comparaison entre bras."
      },
      "R4": {
        "valeur": 1,
        "passage": "ce qui conserve E[e] ≤ 1 sous le nul composite ; e-BH, m, test de mort inchangés."
      },
      "R5": {
        "valeur": 0,
        "motif": "La grille des seuils, les poids du mélange et la formule de calcul de la valeur e ne sont pas spécifiés."
