      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues ; quelques heures de calcul local."
      },
      "R7": {
        "valeur": 1,
        "passage": "afin que la promotion d'une carte conditionnelle atteste une composante hors de ce que l'archive recombine"
